(* meta.ml *)

type uuid = string
type id = uuid
type t = { id : uuid; owner : string }
let make ~id ~owner = { id; owner }
let get _ = failwith "Meta.get: no row source"
let id r = r.id
let owner r = r.owner
let set_id r v = { r with id = v }
let set_owner r v = { r with owner = v }

(* root.ml *)

type id = int
type t = { id : int; meta : Meta.id option; name : string }
let make ~id ~meta ~name = { id; meta; name }
let get _ = failwith "Root.get: no row source"
let id r = r.id
let meta r = r.meta
let name r = r.name
let set_id r v = { r with id = v }
let set_meta r v = { r with meta = v }
let set_name r v = { r with name = v }

(* runs.ml *)

type uuid = string
type id = uuid
type t = { id : uuid; root_id : Root.id; idx : int; ms : float; n : int }
let make ~id ~root_id ~idx ~ms ~n = { id; root_id; idx; ms; n }
let get _ = failwith "Runs.get: no row source"
let of_root _ = failwith "Runs.of_root: no row source"
let id r = r.id
let root_id r = r.root_id
let idx r = r.idx
let ms r = r.ms
let n r = r.n
let set_id r v = { r with id = v }
let set_root_id r v = { r with root_id = v }
let set_idx r v = { r with idx = v }
let set_ms r v = { r with ms = v }
let set_n r v = { r with n = v }
